'use strict';

/**
 * Member scope (FR1). A member sees only orders on which their linked Worker has an assignment
 * (primary or not), the clients of those orders, invoices of those orders and their own Worker.
 * Admins see everything: callers branch on isMember(user) and never call the other helpers for them.
 *
 * Reads process.env.ASSIGNMENTS_TABLE (OrderAssignments: PK orderId, SK workerId, GSI byWorker) and
 * process.env.ORDERS_TABLE (Orders: PK id). Import as require('common/scope').
 *
 * Compute visibleOrderIds once per request and pass the Set around; do not query it twice.
 */

const { GetCommand } = require('@aws-sdk/lib-dynamodb');
const { doc, queryAll, batchGetByIds } = require('../database');

const ASSIGNMENTS_BY_WORKER = 'byWorker';

/** Fails closed: anyone not explicitly an admin is scoped. */
function isMember(user) {
    return !user || user.isAdmin !== true;
}

/** The member's linked Worker id, or null when there is none. */
function memberWorkerId(user) {
    return user && typeof user.workerId === 'string' && user.workerId !== '' ? user.workerId : null;
}

/** Set of order ids the member's Worker is assigned to. Empty when no Worker is linked. */
async function visibleOrderIds(user) {
    const workerId = memberWorkerId(user);
    if (!workerId) return new Set();
    const items = await queryAll({
        TableName: process.env.ASSIGNMENTS_TABLE,
        IndexName: ASSIGNMENTS_BY_WORKER,
        KeyConditionExpression: '#workerId = :workerId',
        ExpressionAttributeNames: { '#workerId': 'workerId', '#orderId': 'orderId' },
        ExpressionAttributeValues: { ':workerId': workerId },
        ProjectionExpression: '#orderId',
    });
    return new Set(items.map((a) => a.orderId));
}

/**
 * True when the member's Worker has an assignment on this order (GetItem on the base key).
 * False when no Worker is linked or orderId is not a string. `consistent` reads the base table
 * strongly (use it before a write).
 */
async function isOrderVisible(user, orderId, { consistent = false } = {}) {
    const workerId = memberWorkerId(user);
    if (!workerId || typeof orderId !== 'string' || orderId === '') return false;
    const res = await doc.send(
        new GetCommand({
            TableName: process.env.ASSIGNMENTS_TABLE,
            Key: { orderId, workerId },
            ProjectionExpression: '#orderId',
            ExpressionAttributeNames: { '#orderId': 'orderId' },
            ConsistentRead: consistent,
        })
    );
    return Boolean(res.Item);
}

/**
 * Clients of the given (visible) orders: { personIds: Set, companyIds: Set }. The client goes to
 * personIds or companyIds by clientType; receivedFromId is always a person.
 */
async function visibleClients(user, orderIds) {
    const personIds = new Set();
    const companyIds = new Set();
    const ids = orderIds ? [...orderIds] : [];
    if (!memberWorkerId(user) || ids.length === 0) return { personIds, companyIds };
    const orders = await batchGetByIds(process.env.ORDERS_TABLE, 'id', ids, ['clientType', 'clientId', 'receivedFromId']);
    for (const o of orders.values()) {
        if (o.clientId) (o.clientType === 'COMPANY' ? companyIds : personIds).add(o.clientId);
        if (o.receivedFromId) personIds.add(o.receivedFromId);
    }
    return { personIds, companyIds };
}

module.exports = { isMember, memberWorkerId, visibleOrderIds, isOrderVisible, visibleClients };
